const baseQuery = `SELECT codigo_bia AS bia_code, contract_id, titulo AS frontier_title, fase_actual AS current_phase, sic AS sic_code, niu, nic, operador_de_red AS grid_operator, tipo_de_mercado AS market_type, tipo_de_medida AS measurement_type, nivel_de_tension AS voltage_level, factor_de_medida AS measurement_factor, energia AS energy_kwh_month, ciudad AS city, departamento AS department, direccion_de_la_frontera AS address, kam_asignado AS kam_assigned, operation_account_executive, numero_de_documento_de_la_empresa AS company_nit, razon_social_de_la_empresa AS company_name, codigo_ciiu AS company_ciiu, propiedad_de_equipos_en_zona AS equipment_ownership, fecha_firma_del_contrato AS contract_sign_date, fecha_real_de_registro AS installation_date, fecha_real_de_activacion AS activation_date, es_frontera_comercial AS is_commercial_border, recibio_paz_y_salvo AS received_paz_y_salvo, fecha_de_vencimiento_de_paz_y_salvo AS paz_y_salvo_expiry_date, numero_de_requerimiento_xm AS xm_requirement_number, razon_on_hold_y_desistimiento AS on_hold_reason, detalle_de_on_hold_y_desistimiento AS on_hold_detail, serial_medidor_registrado AS meter_serial_registered, tiempo_total_gestion_paz_y_salvo_dias AS days_in_paz_y_salvo, tiempo_total_visita_previa_dias AS days_in_visita_previa, tiempo_total_asignacion_equipos_dias AS days_in_asignacion_equipos, tiempo_total_activar_instalar_dias AS days_in_activar_instalar, tiempo_total_completado_dias AS days_in_completado, tiempo_total_on_hold_dias AS days_in_on_hold, tiempo_total_desistidos_dias AS days_in_desistidos, creado_el AS source_created_at FROM operations.hubspot_general WHERE codigo_bia IS NOT NULL ORDER BY codigo_bia`;
const PAGE = 2000;
const MAX_PAGES = 5;
const items = [];
for (let p = 0; p < MAX_PAGES; p++) {
  const offset = p * PAGE;
  const q = baseQuery + ` LIMIT ${PAGE} OFFSET ${offset}`;
  items.push({
    json: {
      page: p,
      offset,
      body: {
        database: 2344,
        type: 'native',
        native: { query: q }
      }
    }
  });
}
return items;

const responses = $input.all().map(i => i.json);
const ingested_at = new Date().toISOString();
let allRows = [];
let cols = null;
for (const r of responses) {
  if (r.error || r.status === 'failed') {
    throw new Error('Metabase error: ' + JSON.stringify(r).slice(0, 300));
  }
  if (!cols && r.data?.cols) cols = r.data.cols.map(c => c.name);
  const rows = r.data?.rows || [];
  allRows = allRows.concat(rows);
}
console.log('fronteras: respuestas=' + responses.length + ', rows totales=' + allRows.length);
if (!cols) return [{ json: {} }];
const out = allRows
  .map(row => ({ ...Object.fromEntries(cols.map((c, i) => [c, row[i]])), ingested_at }))
  .filter(o => o.bia_code != null && String(o.bia_code).trim() !== '');
console.log('fronteras: rows válidas tras filtro PK=' + out.length);
if (!out.length) return [{ json: { _skip: true, count: 0 } }];
return out.map(o => ({ json: o }));

