const items = $input.all();
if (!items.length) return [{ json: { query: 'SELECT 1' } }];
const TABLE = 'opex_cost_items';
const CHUNK = 500;
const Q = "'";
const esc = v => v == null ? 'NULL' : typeof v === 'boolean' ? (v ? 'TRUE' : 'FALSE') : typeof v === 'number' ? String(v) : Q + String(v).replace(/'/g, Q+Q) + Q;
const opexIds = [...new Set(items.map(i => i.json.opex_cost_id).filter(v => v != null))];
if (!opexIds.length) return [{ json: { query: 'SELECT 1' } }];
const cols = Object.keys(items[0].json);
const colList = cols.map(c => '"' + c + '"').join(', ');
const out = [];
out.push({ json: { query: 'DELETE FROM ' + TABLE + ' WHERE opex_cost_id IN (' + opexIds.map(esc).join(', ') + ')' } });
for (let i = 0; i < items.length; i += CHUNK) {
  const vals = items.slice(i, i+CHUNK).map(it => '(' + cols.map(c => esc(it.json[c])).join(',') + ')').join(',');
  out.push({ json: { query: 'INSERT INTO ' + TABLE + ' (' + colList + ') VALUES ' + vals } });
}
return out;

